187:   /**
188:    * Returns the property name if IndexNode contains a property.
189:    * If not, returns null.
190:    * @return {string | null}
191:    */
192:   IndexNode.prototype.getObjectProperty = function () {
193:     return this.isObjectProperty() ? this.dimensions[0].value : null;
