201:   IndexNode.prototype._toString = function (options) {
202:     // format the parameters like "[1, 0:5]"
203:     return this.dotNotation
204:         ? ('.' + this.getObjectProperty())
205:         : ('[' + this.dimensions.join(', ') + ']');
